<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Study;
use App\Domain\Study\Repository\NotebookQuestionExclusionReaderInterface;use App\Infrastructure\Persistence\Doctrine\Performance\Entity\AttemptRecord;use App\Infrastructure\Persistence\Doctrine\Study\Entity\NotebookQuestionRecord;use App\Infrastructure\Persistence\Doctrine\Study\Entity\NotebookRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineNotebookQuestionExclusionReader implements NotebookQuestionExclusionReaderInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function excludedQuestionIds(string $userId,\DateTimeImmutable $since):array { $recent=$this->entityManager->createQueryBuilder()->select('DISTINCT attempt.questionId')->from(AttemptRecord::class,'attempt')->where('attempt.userId=:userId')->andWhere('attempt.completedAt >= :since')->setParameter('userId',$userId)->setParameter('since',$since)->getQuery()->getSingleColumnResult();$reserved=$this->entityManager->createQueryBuilder()->select('DISTINCT selection.questionId')->from(NotebookQuestionRecord::class,'selection')->innerJoin(NotebookRecord::class,'notebook','WITH','notebook.id=selection.notebookId')->where('notebook.userId=:userId')->andWhere('notebook.status IN (:statuses)')->setParameter('userId',$userId)->setParameter('statuses',['DRAFT','IN_PROGRESS','PAUSED'])->getQuery()->getSingleColumnResult();return array_values(array_unique(array_merge($recent,$reserved))); } }
